import { z } from "zod";
import { Config, Signup } from "./schemas";

export type Result<T> = { ok: true; value: T } | { ok: false; problems: string[] };

/**
 * Turn a ZodError into "path: message" lines a human can read.
 *
 * zod 4 dropped the `.errors` alias; the list of issues is `.issues` now.
 */
export function describe(err: z.ZodError): string[] {
  return err.issues.map((e) => `${e.path.join(".") || "(root)"}: ${e.message}`);
}

export function parseSignup(input: unknown): Result<Signup> {
  const r = Signup.safeParse(input);
  return r.success ? { ok: true, value: r.data } : { ok: false, problems: describe(r.error) };
}

export function parseConfig(env: Record<string, unknown>): Result<Config> {
  const r = Config.safeParse(env);
  return r.success ? { ok: true, value: r.data } : { ok: false, problems: describe(r.error) };
}

import { z } from "zod";

export enum Plan {
  Free = "free",
  Pro = "pro",
  Team = "team",
}

const ipv6 = z.ipv6();

/**
 * zod 3's `z.string().ip()` accepted either family in one check; zod 4 split it
 * into `z.ipv4()` / `z.ipv6()`, so accept either to keep the old verdicts.
 * zod 3 also accepted a scoped (zone-indexed) IPv6 address such as
 * "fe80::1%eth0"; zod 4's `ipv6()` rejects the "%zone" suffix, so validate the
 * address part on its own and keep the string exactly as it came in.
 */
const ipAddress = z.union([
  z.ipv4(),
  ipv6,
  z.string().refine((s) => {
    const at = s.indexOf("%");
    return at > 0 && at < s.length - 1 && ipv6.safeParse(s.slice(0, at)).success;
  }),
]);

/** A new account, as posted by the signup form. */
export const Signup = z.object({
  id: z.guid(),
  email: z.email(),
  // zod 4 measures string length in Unicode code points; zod 3 counted UTF-16
  // code units, so an emoji-heavy name that was too long then would squeak
  // through now. Keep zod 3's measure.
  name: z
    .string()
    .refine((s) => s.length >= 1, { message: "String must contain at least 1 character(s)" })
    .refine((s) => s.length <= 80, { message: "String must contain at most 80 character(s)" }),
  // zod 4's `.int()` also caps the value at Number.MAX_SAFE_INTEGER; zod 3 only
  // asked Number.isInteger, so huge integers were accepted.
  age: z
    .number()
    .refine((n) => Number.isInteger(n), { message: "Expected integer, received float" })
    .min(13)
    .optional(),
  website: z.url().optional(),
  ip: ipAddress,
  plan: z.enum(Plan),
  /** feature flags, e.g. { beta: true } */
  flags: z.record(z.string(), z.boolean()),
  prefs: z
    .object({
      theme: z.enum(["light", "dark"]).default("light"),
      /** comes in as a string from the form; stored as a number */
      retries: z.string().transform(Number).prefault("3"),
    })
    // `prefault`, not `default`: the fallback is fed *through* the schema, the
    // way zod 3's `.default({})` did, so the inner defaults still fill in.
    .prefault({}),
});
export type Signup = z.infer<typeof Signup>;

/** Service config, usually read from environment variables (so: strings). */
export const Config = z.object({
  port: z.string().transform(Number).prefault("8080"),
  hosts: z.array(ipAddress).min(1),
  timeoutMs: z.number().positive().default(5000),
});
export type Config = z.infer<typeof Config>;

/** A webhook handler: (event, payloadBytes) => void, checked at the boundary. */
export const Hook = z.function({
  input: [z.string(), z.number()],
  output: z.void(),
});

